Here's a complete, self-contained checkout screen for a Telegram Mini App — cart list, delivery address form with validation, a Pay button, and a back-to-cart action. Two files: the component and its stylesheet.

```tsx
// CheckoutScreen.tsx
import React, { useMemo, useState } from "react";
import "./CheckoutScreen.css";

export interface CartItem {
  id: string;
  name: string;
  imageUrl?: string;
  price: number;
  quantity: number;
}

export interface DeliveryAddress {
  fullName: string;
  phone: string;
  city: string;
  street: string;
  apartment?: string;
  postalCode: string;
  comment?: string;
}

export interface CheckoutScreenProps {
  items: CartItem[];
  currencySymbol?: string;
  deliveryFee?: number;
  isSubmitting?: boolean;
  onBack: () => void;
  onPay: (address: DeliveryAddress) => void;
}

type FormErrors = Partial<Record<keyof DeliveryAddress, string>>;

const INITIAL_ADDRESS: DeliveryAddress = {
  fullName: "",
  phone: "",
  city: "",
  street: "",
  apartment: "",
  postalCode: "",
  comment: "",
};

function formatPrice(value: number, currencySymbol: string): string {
  return `${currencySymbol}${value.toFixed(2)}`;
}

function validate(address: DeliveryAddress): FormErrors {
  const errors: FormErrors = {};

  if (!address.fullName.trim()) {
    errors.fullName = "Full name is required";
  }

  if (!address.phone.trim()) {
    errors.phone = "Phone number is required";
  } else if (!/^[+\d][\d\s()-]{6,}$/.test(address.phone.trim())) {
    errors.phone = "Enter a valid phone number";
  }

  if (!address.city.trim()) {
    errors.city = "City is required";
  }

  if (!address.street.trim()) {
    errors.street = "Street address is required";
  }

  if (!address.postalCode.trim()) {
    errors.postalCode = "Postal code is required";
  }

  return errors;
}

export default function CheckoutScreen({
  items,
  currencySymbol = "$",
  deliveryFee = 0,
  isSubmitting = false,
  onBack,
  onPay,
}: CheckoutScreenProps) {
  const [address, setAddress] = useState<DeliveryAddress>(INITIAL_ADDRESS);
  const [errors, setErrors] = useState<FormErrors>({});
  const [touched, setTouched] = useState<Partial<Record<keyof DeliveryAddress, boolean>>>({});

  const subtotal = useMemo(
    () => items.reduce((sum, item) => sum + item.price * item.quantity, 0),
    [items]
  );
  const total = subtotal + deliveryFee;

  const handleChange = (field: keyof DeliveryAddress) => (
    e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>
  ) => {
    const value = e.target.value;
    setAddress((prev) => ({ ...prev, [field]: value }));
  };

  const handleBlur = (field: keyof DeliveryAddress) => () => {
    setTouched((prev) => ({ ...prev, [field]: true }));
    setErrors(validate(address));
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const validationErrors = validate(address);
    setErrors(validationErrors);
    setTouched({
      fullName: true,
      phone: true,
      city: true,
      street: true,
      postalCode: true,
    });

    if (Object.keys(validationErrors).length === 0) {
      onPay(address);
    }
  };

  const fieldError = (field: keyof DeliveryAddress) =>
    touched[field] ? errors[field] : undefined;

  const isEmpty = items.length === 0;

  return (
    <div className="checkout">
      <header className="checkout__header">
        <button
          type="button"
          className="checkout__back-btn"
          onClick={onBack}
          aria-label="Back to cart"
        >
          <svg
            width="20"
            height="20"
            viewBox="0 0 24 24"
            fill="none"
            aria-hidden="true"
          >
            <path
              d="M15 18l-6-6 6-6"
              stroke="currentColor"
              strokeWidth="2"
              strokeLinecap="round"
              strokeLinejoin="round"
            />
          </svg>
        </button>
        <h1 className="checkout__title">Checkout</h1>
        <span className="checkout__header-spacer" aria-hidden="true" />
      </header>

      <form className="checkout__form" onSubmit={handleSubmit}>
        <section className="checkout__section">
          <h2 className="checkout__section-title">Your order</h2>

          {isEmpty ? (
            <p className="checkout__empty">Your cart is empty.</p>
          ) : (
            <ul className="checkout__items">
              {items.map((item) => (
                <li key={item.id} className="checkout__item">
                  <div className="checkout__item-thumb">
                    {item.imageUrl ? (
                      <img src={item.imageUrl} alt={item.name} />
                    ) : (
                      <div className="checkout__item-thumb-placeholder" />
                    )}
                  </div>
                  <div className="checkout__item-info">
                    <span className="checkout__item-name">{item.name}</span>
                    <span className="checkout__item-qty">
                      Qty {item.quantity} ×{" "}
                      {formatPrice(item.price, currencySymbol)}
                    </span>
                  </div>
                  <span className="checkout__item-total">
                    {formatPrice(item.price * item.quantity, currencySymbol)}
                  </span>
                </li>
              ))}
            </ul>
          )}

          <div className="checkout__summary">
            <div className="checkout__summary-row">
              <span>Subtotal</span>
              <span>{formatPrice(subtotal, currencySymbol)}</span>
            </div>
            <div className="checkout__summary-row">
              <span>Delivery</span>
              <span>
                {deliveryFee === 0
                  ? "Free"
                  : formatPrice(deliveryFee, currencySymbol)}
              </span>
            </div>
            <div className="checkout__summary-row checkout__summary-row--total">
              <span>Total</span>
              <span>{formatPrice(total, currencySymbol)}</span>
            </div>
          </div>
        </section>

        <section className="checkout__section">
          <h2 className="checkout__section-title">Delivery address</h2>

          <div className="checkout__field">
            <label htmlFor="fullName">Full name</label>
            <input
              id="fullName"
              type="text"
              autoComplete="name"
              value={address.fullName}
              onChange={handleChange("fullName")}
              onBlur={handleBlur("fullName")}
              className={fieldError("fullName") ? "checkout__input--error" : ""}
              placeholder="Jane Doe"
            />
            {fieldError("fullName") && (
              <span className="checkout__field-error">{fieldError("fullName")}</span>
            )}
          </div>

          <div className="checkout__field">
            <label htmlFor="phone">Phone number</label>
            <input
              id="phone"
              type="tel"
              autoComplete="tel"
              value={address.phone}
              onChange={handleChange("phone")}
              onBlur={handleBlur("phone")}
              className={fieldError("phone") ? "checkout__input--error" : ""}
              placeholder="+1 555 123 4567"
            />
            {fieldError("phone") && (
              <span className="checkout__field-error">{fieldError("phone")}</span>
            )}
          </div>

          <div className="checkout__field-row">
            <div className="checkout__field">
              <label htmlFor="city">City</label>
              <input
                id="city"
                type="text"
                autoComplete="address-level2"
                value={address.city}
                onChange={handleChange("city")}
                onBlur={handleBlur("city")}
                className={fieldError("city") ? "checkout__input--error" : ""}
                placeholder="New York"
              />
              {fieldError("city") && (
                <span className="checkout__field-error">{fieldError("city")}</span>
              )}
            </div>

            <div className="checkout__field">
              <label htmlFor="postalCode">Postal code</label>
              <input
                id="postalCode"
                type="text"
                autoComplete="postal-code"
                value={address.postalCode}
                onChange={handleChange("postalCode")}
                onBlur={handleBlur("postalCode")}
                className={fieldError("postalCode") ? "checkout__input--error" : ""}
                placeholder="10001"
              />
              {fieldError("postalCode") && (
                <span className="checkout__field-error">{fieldError("postalCode")}</span>
              )}
            </div>
          </div>

          <div className="checkout__field">
            <label htmlFor="street">Street address</label>
            <input
              id="street"
              type="text"
              autoComplete="address-line1"
              value={address.street}
              onChange={handleChange("street")}
              onBlur={handleBlur("street")}
              className={fieldError("street") ? "checkout__input--error" : ""}
              placeholder="123 Main St"
            />
            {fieldError("street") && (
              <span className="checkout__field-error">{fieldError("street")}</span>
            )}
          </div>

          <div className="checkout__field">
            <label htmlFor="apartment">Apartment / unit (optional)</label>
            <input
              id="apartment"
              type="text"
              autoComplete="address-line2"
              value={address.apartment}
              onChange={handleChange("apartment")}
              placeholder="Apt 4B"
            />
          </div>

          <div className="checkout__field">
            <label htmlFor="comment">Delivery notes (optional)</label>
            <textarea
              id="comment"
              rows={3}
              value={address.comment}
              onChange={handleChange("comment")}
              placeholder="Leave at the front desk, ring the bell, etc."
            />
          </div>
        </section>

        <div className="checkout__footer">
          <button
            type="button"
            className="checkout__secondary-btn"
            onClick={onBack}
            disabled={isSubmitting}
          >
            Back to cart
          </button>
          <button
            type="submit"
            className="checkout__pay-btn"
            disabled={isEmpty || isSubmitting}
          >
            {isSubmitting
              ? "Processing…"
              : `Pay ${formatPrice(total, currencySymbol)}`}
          </button>
        </div>
      </form>
    </div>
  );
}
```

